//! Error types for Kali

use std::fmt;

use ariadne::{Label, Report, ReportKind};
use kali_parse::chumsky::util::Maybe;
use kali_span::WithSpan;

/// An error generated by the Kali compiler, with context about where the error
/// occurred.
pub struct Error {
    /// The kind of error that occurred.
    kind: ErrorKind,
    /// The context in which the error occurred, providing information about the
    /// source of the error.
    context: kali_span::Context,
}

/// Enumeration of the kinds of errors that can occur during compilation.
pub enum ErrorKind {
    Io(std::io::Error),
    /// A syntax or lexical error occurred.
    Parse(ParseError),
    /// A type error occurred.
    Type(kali_type::Error),
}

/// A syntax error, extracted from the parser's borrowed error type so that it
/// can outlive the source text it was produced from.
#[derive(Debug, Clone)]
pub struct ParseError {
    /// A description of the unexpected token, or end of input.
    pub found: Option<kali_parse::TokenKind>,
    /// A description of the tokens that were expected instead.
    pub expected: Vec<Expected>,
    /// Spanned contents from the source code that caused the error, including
    /// the context in which it occurred.
    pub contexts: Vec<kali_span::Spanned<Box<str>>>,
    /// The top-level span of the error, which may be a superset of the spans in
    /// `contexts`.
    pub span: kali_span::Span,
}

/// An expected token or label, used to describe what the parser expected to
/// find at a given point in the source code.
#[derive(Debug, Clone)]
pub enum Expected {
    /// A specific token that was expected.
    Token(kali_parse::TokenKind),
    /// A specific identifier that was expected.
    Identifier(Box<str>),
    /// A label describing what was expected, such as "identifier" or
    /// "expression".
    Label(Box<str>),
    /// The end of input was expected.
    EndOfInput,
}

impl fmt::Display for Expected {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expected::Token(tok) => write!(f, "`{}`", tok),
            Expected::Identifier(ident) => write!(f, "identifier `{}`", ident),
            Expected::Label(label) => write!(f, "{}", label),
            Expected::EndOfInput => write!(f, "end of input"),
        }
    }
}

impl<'src> From<kali_parse::Error<'src>> for ParseError {
    fn from(error: kali_parse::Error<'src>) -> Self {
        Self {
            found: error.found().map(Into::into),
            expected: error.expected().map(Into::into).collect::<Vec<_>>(),
            contexts: error
                .contexts()
                .map(|(pat, span)| kali_span::Spanned {
                    value: pat.to_string().into_boxed_str(),
                    span: *span,
                })
                .collect::<Vec<_>>(),
            span: error.span().clone(),
        }
    }
}

impl From<&kali_parse::chumsky::error::RichPattern<'_, kali_parse::Token<'_>>> for Expected {
    fn from(pattern: &kali_parse::chumsky::error::RichPattern<'_, kali_parse::Token<'_>>) -> Self {
        use kali_parse::chumsky::error::RichPattern;
        match pattern {
            RichPattern::Token(maybe) => maybe.into(),
            RichPattern::Label(cow) => Expected::Label(cow.clone().into_owned().into_boxed_str()),
            RichPattern::Identifier(val) => Expected::Label(val.clone().into_boxed_str()),
            RichPattern::EndOfInput => Expected::EndOfInput,
            RichPattern::SomethingElse => Expected::Label("something else".into()),
            RichPattern::Any | _ => unreachable!(),
        }
    }
}

impl<'src> From<&Maybe<kali_parse::Token<'src>, &kali_parse::Token<'src>>> for Expected {
    fn from(maybe: &Maybe<kali_parse::Token<'src>, &kali_parse::Token<'src>>) -> Self {
        match maybe {
            Maybe::Ref(tok) => Expected::Token((*tok).into()),
            Maybe::Val(tok) => Expected::Token(tok.into()),
        }
    }
}

impl Error {
    /// Get the kind of error that occurred.
    pub fn kind(&self) -> &ErrorKind {
        &self.kind
    }

    /// Get the context in which the error occurred.
    pub fn context(&self) -> &kali_span::Context {
        &self.context
    }

    /// Set the context in which the error occurred.
    pub fn with_context(mut self, context: kali_span::Context) -> Self {
        self.context = context;
        self
    }

    /// Convert this error into an `ariadne::Report`, which can be used to
    /// display the error to the user.
    pub fn into_report(self) -> Report<'static, kali_span::Span> {
        match self.kind {
            ErrorKind::Io(e) => Self::into_io_report(self.context, e),
            ErrorKind::Parse(e) => Self::into_syntax_report(self.context, e),
            ErrorKind::Type(e) => Self::into_type_report(self.context, e),
        }
    }

    /// Convert an I/O error into an `ariadne::Report`.
    fn into_io_report(
        context: kali_span::Context,
        error: std::io::Error,
    ) -> Report<'static, kali_span::Span> {
        Report::build(ReportKind::Error, context.src, 0)
            .with_message(format!("I/O error: {}", error))
            .finish()
    }

    /// Convert a syntax error into an `ariadne::Report`.
    fn into_syntax_report(
        context: kali_span::Context,
        error: ParseError,
    ) -> Report<'static, kali_span::Span> {
        let found = match error.found {
            Some(tok) => format!("Unexpected token: {}", tok),
            None => "Unexpected end of input".to_string(),
        };

        // Build a string representation of the expected tokens or labels.
        let mut expected = if error.expected.len() == 1 {
            format!("Expected {}", error.expected[0])
        } else {
            "Expected one of ".to_string()
        };
        for (i, item) in error.expected.iter().map(ToString::to_string).enumerate() {
            if i > 0 {
                expected.push_str(", ");
            } else if i == error.expected.len() - 1 {
                expected.push_str(", or ");
            }
            expected.push_str(&item);
        }

        Report::build(ariadne::ReportKind::Error, context.src, error.span.start)
            .with_config(ariadne::Config::default().with_index_type(ariadne::IndexType::Byte))
            .with_message(found)
            .with_label(Label::new(error.span).with_message(expected))
            .finish()
    }

    /// Convert a list of type errors into an `ariadne::Report`.
    fn into_type_report(
        context: kali_span::Context,
        error: kali_type::Error,
    ) -> Report<'static, kali_span::Span> {
        todo!()
    }
}

impl From<std::io::Error> for Error {
    fn from(error: std::io::Error) -> Self {
        Self { kind: ErrorKind::Io(error), context: kali_span::Context::default() }
    }
}

impl<'src> From<kali_parse::Error<'src>> for Error {
    fn from(error: kali_parse::Error<'src>) -> Self {
        let span = *error.span();
        Self { kind: ErrorKind::Parse(error.into()), context: span.context }
    }
}

impl From<kali_type::Error> for Error {
    fn from(error: kali_type::Error) -> Self {
        Self { kind: ErrorKind::Type(error), context: kali_span::Context::default() }
    }
}
